<style>
.static-hero{padding:56px 0 46px;background:radial-gradient(circle at 80% 20%,#dceeff,transparent 38%),linear-gradient(145deg,#f8fcff,#edf7ff);border-top:1px solid #edf2f8}.static-hero h1{margin:14px 0 12px;font-size:46px;line-height:1.08;letter-spacing:-1.6px}.static-hero p{max-width:760px;margin:0;color:#56708f;font-size:16px;line-height:1.7}.static-meta{display:flex;flex-wrap:wrap;gap:8px 18px;margin-top:16px;color:#70839e;font-size:12px;font-weight:700}.static-stage{padding:50px 0 80px}.static-layout{display:grid;grid-template-columns:230px minmax(0,780px);justify-content:center;align-items:start;gap:34px}.static-toc{position:sticky;top:24px;padding:19px;border:1px solid #dce8f6;border-radius:16px;background:#fff;box-shadow:0 12px 32px rgba(34,75,128,.07)}.static-toc strong{display:flex;align-items:center;gap:8px;margin-bottom:12px;color:#18345a;font-size:12px;text-transform:uppercase;letter-spacing:.07em}.static-toc a{display:block;padding:7px 8px;border-left:2px solid transparent;border-radius:0 7px 7px 0;color:#697d97;font-size:12px;line-height:1.4}.static-toc a:hover{border-left-color:#2166f3;background:#eef5ff;color:#1e5dcc}.static-card{padding:42px 46px 46px;border:1px solid #e0eaf5;border-radius:22px;background:#fff;box-shadow:0 18px 55px rgba(34,76,130,.08)}.static-content{color:#304762;font-size:16px;line-height:1.82}.static-content h2{scroll-margin-top:24px;margin:38px 0 12px;color:#122a4a;font-size:26px;line-height:1.3}.static-content h2:first-child{margin-top:0}.static-content h3{margin:24px 0 8px;color:#1b3557;font-size:18px}.static-content p{margin:0 0 15px}.static-content ul,.static-content ol{margin:0 0 18px;padding-left:22px}.static-content li{margin:6px 0}.static-content a{color:#2166f3;text-decoration:underline;text-underline-offset:3px}.static-content table{width:100%;margin:18px 0 24px;border-collapse:separate;border-spacing:0;border:1px solid #dce7f4;border-radius:12px;overflow:hidden}.static-content th,.static-content td{padding:12px 14px;border-bottom:1px solid #e3ebf5;text-align:left;vertical-align:top;font-size:14px}.static-content th{background:#edf5ff;color:#18345a}.static-content tr:last-child td{border-bottom:0}.static-content .note{margin:22px 0;padding:16px 18px;border-left:4px solid #2166f3;border-radius:9px;background:#eef5ff;color:#27456d}.static-content .warn{border-left-color:#f0a029;background:#fff8e9;color:#6e5426}.contact-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px;margin:20px 0 28px}.contact-card{padding:20px;border:1px solid #dce7f3;border-radius:14px;background:#f8fbff}.contact-card i{display:grid;place-items:center;width:40px;height:40px;margin-bottom:12px;border-radius:11px;background:#e8f2ff;color:#2166f3;font-size:19px}.contact-card strong{display:block;margin-bottom:6px;color:#152746;font-size:16px}.contact-card p{margin:0 0 10px;color:#5f7190;font-size:13px;line-height:1.6}.contact-card a.mail{display:inline-block;padding:8px 12px;border-radius:8px;background:#2166f3;color:#fff;font-size:13px;font-weight:800;text-decoration:none}.principles{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;margin:18px 0 26px}.principles div{padding:16px 18px;border:1px solid #dce7f3;border-radius:12px;background:#f8fbff}.principles strong{display:block;margin-bottom:5px;color:#152746}.principles span{color:#5f7190;font-size:13px;line-height:1.6}@media(max-width:950px){.static-layout{grid-template-columns:1fr;max-width:800px;margin:auto}.static-toc{position:static}}@media(max-width:620px){.static-hero{padding:40px 0 34px}.static-hero h1{font-size:34px;letter-spacing:-1px}.static-stage{padding:28px 0 54px}.static-card{padding:26px 20px 30px;border-radius:17px}.static-content{font-size:15px}.static-content h2{font-size:22px}.static-content table{display:block;overflow-x:auto}.contact-grid,.principles{grid-template-columns:1fr}}
</style>
